import os,re,sys,json

DECL=re.compile(r'^(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|nonrec\s+|partial\s+|unsafe\s+|scoped\s+)*(theorem|lemma|def|abbrev|instance|structure|class|inductive|opaque|axiom)\s+([A-Za-z_α-ωΑ-Ωᵢ-ᵪ\U0001d49c-\U0001d59f\'₀-₉][^\s:({\[]*)')
NS=re.compile(r'^(namespace|end)\s+(\S+)\s*$')

def index_project(root):
    """returns dict fqname -> (relpath, lineno, kind), and dict relpath -> [fqnames]"""
    decls={}
    byfile={}
    for dp,dn,fn in os.walk(root):
        if '.lake' in dp: continue
        for f in fn:
            if not f.endswith('.lean'): continue
            p=os.path.join(dp,f)
            rel=os.path.relpath(p,root)
            stack=[]
            byfile[rel]=[]
            insec=0
            try: lines=open(p,encoding='utf-8').read().split('\n')
            except: continue
            inblock=False
            for i,line in enumerate(lines,1):
                # crude block comment skip
                if not inblock and (line.lstrip().startswith('/-')) and '-/' not in line:
                    inblock=True; continue
                if inblock:
                    if '-/' in line: inblock=False
                    continue
                m=NS.match(line.rstrip())
                if m:
                    if m.group(1)=='namespace':
                        stack.append(m.group(2))
                    else:
                        if stack and stack[-1]==m.group(2): stack.pop()
                    continue
                if line.rstrip()=='end' :
                    continue
                m=DECL.match(line)
                if m:
                    kind,name=m.group(1),m.group(2)
                    if name.endswith('.'): continue
                    fq='.'.join(stack+[name]) if stack else name
                    decls.setdefault(fq,(rel,i,kind))
                    byfile[rel].append(fq)
    return decls,byfile

if __name__=='__main__':
    root=sys.argv[1]; out=sys.argv[2]
    d,bf=index_project(root)
    json.dump({'decls':d,'byfile':bf},open(out,'w'))
    print(root, "decls:", len(d))
